{
  "userQuery": "雨天打车卡片,主图标用小雨伞,横排三个固定目的地(公司/家/学校)用主题色背景配蓝紫氛围渐变。点\"设置提醒\"跳到闹钟应用,纯文字色块不要图片,文案固定就行。",
  "size": "2x4",
  "eventCandidates": [
    {
      "call": "clickToDeeplink",
      "args": {
        "bundleName": "com.huawei.deskclock",
        "abilityName": "com.huawei.deskclock.MainAbility",
        "uri": "clock://alarm"
